ipfw.remove = function(num, cb) {
  var del = 'ipfw delete '+num;
  child_process.exec(del, function(err, stdout, stderr){
    if (err) return cb(err);
    if (stderr) return cb(stderr);
    cb(null, stdout);
  });
};
